package com.estoqueinteligente.supplier;
import java.time.Instant;import jakarta.persistence.*;
@Entity @Table(name="suppliers") public class Supplier{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=150)private String name;@Column(length=30)private String phone;@Column(length=150)private String email;@Column(name="contact_person",length=120)private String contactPerson;@Column(columnDefinition="TEXT")private String notes;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@PrePersist void create(){createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();}public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getContactPerson(){return contactPerson;}public void setContactPerson(String v){contactPerson=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
